# -*- coding: utf-8 -*-
P1 = "Cari kalimat yang menyatakan pendapat/alasan penulis (〜からだ、〜と思う、しかし〜)."
P2 = "Cocokkan setiap pilihan dengan teks; pilihan yang menambahkan hal yang tidak ada di teks adalah salah."
CN = 'Teks menengah (内容理解・中文)'; LN = 'Teks panjang (内容理解・長文)'
W = ['Tidak disebut dalam teks.', 'Tidak sesuai dengan isi teks.', 'Bertentangan dengan isi teks.']
def C(jp, idt, *qs): return dict(slot='chu', jenis=CN, jp=jp, id=idt, qs=[(q, o, a, al, bk, W, p) for (q, o, a, al, bk, p) in qs])
def L(jp, idt, *qs): return dict(slot='cho', jenis=LN, jp=jp, id=idt, qs=[(q, o, a, al, bk, W, p) for (q, o, a, al, bk, p) in qs])
B = [
 C('最近、会社で在宅勤務が認められるようになった。通勤時間がなくなり、朝の時間に余裕ができたのはありがたい。しかし、家では仕事とそれ以外の境目があいまいになりやすい。\n私は、仕事を始める時間と終える時間を決め、仕事用の机も用意した。そうすると、気持ちの切り替えがしやすくなり、集中できる時間も増えた。','Belakangan kantor mengizinkan kerja dari rumah. Waktu komuter hilang dan pagi lebih longgar, tapi di rumah batas kerja dan non-kerja mudah kabur. Saya menetapkan jam mulai dan selesai serta menyiapkan meja kerja. Dengan begitu peralihan perasaan lebih mudah dan waktu fokus bertambah.',
   ('在宅勤務のよくない点は何か。',['仕事とそれ以外の境目があいまいになりやすい','通勤時間が長い','給料が下がる','上司に会えない'],0,'Batas kabur.','境目があいまいになりやすい',P1),
   ('「私」が工夫したことは何か。',['仕事の時間を決めて仕事用の机を用意した','毎日外で働いた','同僚と一緒に働いた','夜に仕事をした'],0,'Menetapkan jam dan menyiapkan meja.','仕事を始める時間と終える時間を決め、仕事用の机も用意した',P2)),
 C('日本では、ごみの分別が細かく決まっている。町によっては、燃えるごみ、燃えないごみ、資源ごみなど十種類以上に分ける。外国から来た人には、最初は難しく感じられる。\nしかし、分別をすることで、資源が再利用され、ごみの量も減らせる。私も初めは面倒だと思ったが、慣れると、環境のために自分ができることをしているという気持ちになった。','Di Jepang pemilahan sampah diatur rinci. Di beberapa kota dipisah menjadi lebih dari sepuluh jenis. Bagi orang asing awalnya sulit. Namun dengan pemilahan, sumber daya didaur ulang dan volume sampah berkurang. Saya awalnya merasa repot, tapi setelah terbiasa merasa melakukan sesuatu untuk lingkungan.',
   ('分別を続けるとどんな良いことがあるか。',['資源が再利用され、ごみの量が減る','お金がもらえる','ごみ収集が毎日になる','町が広くなる'],0,'Sumber daya didaur ulang dan sampah berkurang.','資源が再利用され、ごみの量も減らせる',P1),
   ('「私」は慣れたあと、どう感じたか。',['環境のために自分ができることをしていると感じた','やはり面倒だと感じた','意味がないと感じた','もうやめたいと感じた'],0,'Merasa berbuat untuk lingkungan.','環境のために自分ができることをしているという気持ち',P2)),
 C('私の趣味は、古い写真を集めることだ。町の古道具屋で、百年前の家族写真を見つけたこともある。写っている人がだれかは分からないが、服装や表情から、その時代の暮らしが想像できる。\n先日、その写真を地元の資料館に見せたところ、大変貴重なものだと言われ、展示してもらえることになった。私は、自分の趣味が人の役に立ったことが嬉しかった。','Hobi saya mengumpulkan foto lama. Di toko barang bekas saya pernah menemukan foto keluarga seratus tahun lalu. Siapa yang ada di foto tidak diketahui tapi dari pakaian dan ekspresi bisa membayangkan kehidupan saat itu. Baru-baru ini foto saya tunjukkan ke museum setempat dan dibilang sangat berharga, sehingga akan dipamerkan. Saya senang hobi saya berguna.',
   ('「私」は古い写真から何が想像できると言っているか。',['その時代の暮らし','写っている人の名前','写真家の人生','写真の値段'],0,'Kehidupan zaman itu.','その時代の暮らしが想像できる',P1),
   ('資料館は写真をどうすることになったか。',['展示する','売る','修理する','返す'],0,'Dipamerkan.','展示してもらえることになった',P2)),
 C('電車の中で、赤ちゃんを連れた女性に席をゆずる人を見かけた。女性は「ありがとうございます」と笑顔で座り、周りの人も温かい気持ちになったように見えた。\n私は、こうした小さな親切が、実は社会を支えているのだと思う。声に出すのが恥ずかしいときもあるが、小さな行動から始めたいと思った。','Di kereta saya melihat seseorang memberikan tempat duduk kepada ibu yang membawa bayi. Ibu itu tersenyum dan berterima kasih dan orang di sekitar tampak hangat hatinya. Saya pikir kebaikan kecil seperti ini sebenarnya menopang masyarakat. Kadang malu bersuara tapi saya ingin mulai dari tindakan kecil.',
   ('「私」は小さな親切をどう考えているか。',['実は社会を支えている','意味がない','恥ずかしいだけだ','女性だけがするものだ'],0,'Sebenarnya menopang masyarakat.','社会を支えているのだと思う',P1),
   ('「私」はこれからどうしたいか。',['小さな行動から始めたい','電車に乗らないようにしたい','大きな活動をしたい','何もしないでいたい'],0,'Mulai dari tindakan kecil.','小さな行動から始めたい',P2)),
 C('最近、若い人の間で「ミニマリスト」という生き方が注目されている。必要な物だけを持ち、部屋をすっきりさせる暮らし方だ。物が少ないと掃除が楽で、探し物にかける時間も減る。\nただし、無理に物を捨てると、後で困ることもある。大切なのは、自分にとって本当に必要なものは何かを考えることだと、専門家は話している。','Belakangan di kalangan anak muda gaya hidup minimalis menjadi perhatian. Hanya memiliki barang perlu dan merapikan kamar. Barang sedikit memudahkan bersih-bersih dan mengurangi waktu mencari barang. Tapi membuang barang berlebihan bisa merepotkan nanti. Yang penting memikirkan apa yang benar-benar dibutuhkan, kata pakar.',
   ('ミニマリストの暮らしの利点は何か。',['掃除が楽で探し物の時間が減る','お金がたくさんもらえる','部屋が広くなる','友達が増える'],0,'Bersih-bersih mudah dan waktu mencari berkurang.','掃除が楽で、探し物にかける時間も減る',P1),
   ('専門家は何が大切だと言っているか。',['本当に必要なものは何かを考えること','できるだけ多く捨てること','新しい物を買うこと','部屋を広くすること'],0,'Memikirkan apa yang benar-benar perlu.','本当に必要なものは何かを考えること',P2)),
 C('私が住む町には、小さな商店街がある。以前は多くの店が並んでいたが、大きなスーパーができてから、閉める店が増えた。\nそこで、商店街の人たちは、毎月イベントを開くことにした。地元の野菜を売る市や、子どもが遊べる広場を作ると、また人が戻ってきた。商店街の人は「みんなが集まれる場所にすることが大切だ」と話している。','Di kota saya ada pertokoan kecil. Dulu banyak toko berjajar, tapi sejak ada supermarket besar banyak toko tutup. Karena itu para pedagang mengadakan acara tiap bulan. Setelah membuat pasar sayur lokal dan lapangan bermain anak orang kembali. Mereka bilang yang penting menjadikannya tempat berkumpul.',
   ('商店街の店が減った理由は何か。',['大きなスーパーができたから','町の人が減ったから','店主が高齢になったから','駅がなくなったから'],0,'Karena ada supermarket besar.','大きなスーパーができてから、閉める店が増えた',P1),
   ('商店街の人はどうして人が戻ってきたと考えているか。',['みんなが集まれる場所にしたから','値段を下げたから','店を広くしたから','夜遅くまで開けたから'],0,'Menjadikannya tempat berkumpul.','みんなが集まれる場所にすることが大切',P2)),
 C('私は先月、初めて一人で海外旅行に行った。言葉が通じるか不安だったが、簡単な英語と身ぶりで、意外となんとかなった。困っていると、地元の人が親切に助けてくれた。\n帰国して、「知らない場所に飛びこんでみると、自分の世界が広がる」ということを実感した。次は、もっと遠い国に行ってみたい。','Bulan lalu saya pertama kali berwisata sendirian ke luar negeri. Cemas apakah bahasa terpahami, tapi dengan bahasa Inggris sederhana dan isyarat ternyata bisa. Saat kesulitan, orang setempat menolong dengan ramah. Setelah pulang saya merasakan bahwa jika terjun ke tempat asing dunia kita meluas. Selanjutnya ingin ke negara lebih jauh.',
   ('旅行中、「私」はどうやって困難を乗り越えたか。',['簡単な英語と身ぶりを使った','通訳を頼んだ','日本語だけで話した','友達に電話した'],0,'Bahasa Inggris sederhana dan isyarat.','簡単な英語と身ぶりで',P1),
   ('「私」が旅行で感じたことは何か。',['知らない場所に飛びこむと自分の世界が広がる','もう旅行はしたくない','言葉が一番大切だ','一人旅は危険だ'],0,'Dunia meluas.','自分の世界が広がる',P2)),
 C('日本の学校では、生徒が毎日、自分たちで教室を掃除する。外国から来た人は驚くことが多いが、日本ではこれは教育の一部と考えられている。\n自分で使う場所を自分できれいにすることで、物を大切にする気持ちや、協力する心が育つと言われている。ただし、時間がかかるため、授業時間が減ると心配する声もある。','Di sekolah Jepang murid membersihkan kelas sendiri tiap hari. Orang asing sering kaget tapi di Jepang ini dianggap bagian dari pendidikan. Dengan membersihkan tempat yang dipakai sendiri, tumbuh rasa menghargai barang dan semangat kerja sama. Tapi karena makan waktu ada yang khawatir jam pelajaran berkurang.',
   ('日本の学校で掃除をする目的は何か。',['物を大切にする気持ちや協力する心を育てること','掃除の人を雇わないこと','学校を安くすること','運動すること'],0,'Menumbuhkan rasa menghargai dan kerja sama.','物を大切にする気持ちや、協力する心が育つ',P1),
   ('掃除に対する心配は何か。',['授業時間が減ること','お金がかかること','けがをすること','ごみが増えること'],0,'Jam pelajaran berkurang.','授業時間が減ると心配する声もある',P2)),
 C('私は毎朝、近所の公園を散歩している。早い時間は人が少なく、鳥の声が聞こえて気持ちがいい。最近、同じ時間に散歩する人たちと顔見知りになり、挨拶を交わすようになった。\n最初は知らない人に話しかけるのが苦手だったが、毎日会ううちに、自然に話せるようになった。散歩が、体だけでなく人間関係にもいい影響を与えていると感じる。','Tiap pagi saya jalan-jalan di taman dekat rumah. Pagi hari sepi, terdengar kicau burung dan nyaman. Belakangan saya mengenal orang-orang yang jalan pada jam yang sama dan saling menyapa. Awalnya tak pandai menyapa orang asing, tapi sering bertemu jadi bisa bicara alami. Saya merasa jalan pagi berpengaruh baik bukan hanya pada tubuh tapi juga hubungan antarmanusia.',
   ('散歩のよい点は何か。',['体だけでなく人間関係にもいい影響がある','お金が稼げる','仕事が早く終わる','料理がうまくなる'],0,'Baik bagi tubuh dan hubungan antarmanusia.','体だけでなく人間関係にもいい影響',P1),
   ('「私」は最初、何が苦手だったか。',['知らない人に話しかけること','早く起きること','歩くこと','鳥の声を聞くこと'],0,'Menyapa orang asing.','知らない人に話しかけるのが苦手',P2)),
 C('インターネットで買い物をすると、店に行く手間が省け、いつでも注文できる。重い物も家まで届けてくれるので、特にお年寄りには便利だ。\nしかし、実際に手に取って見られないため、「思っていたのと違う」ということも少なくない。返品できる店を選ぶことが、失敗を防ぐ一つの方法だ。','Berbelanja lewat internet menghemat repot ke toko dan bisa memesan kapan saja. Barang berat diantar ke rumah sehingga terutama praktis bagi lansia. Namun karena tak bisa dipegang langsung, tak jarang berbeda dari bayangan. Memilih toko yang bisa menerima retur adalah salah satu cara mencegah kegagalan.',
   ('ネットショッピングの利点は何か。',['店に行く手間が省けいつでも注文できる','実物を見られる','値段が必ず安い','すぐ商品が届く'],0,'Hemat repot dan bisa kapan saja.','店に行く手間が省け、いつでも注文できる',P1),
   ('失敗を防ぐ方法は何か。',['返品できる店を選ぶ','高い物を買う','たくさん注文する','実物を見ずに買う'],0,'Memilih toko yang bisa retur.','返品できる店を選ぶこと',P2)),
 C('私は大学生のとき、カフェでアルバイトをしていた。最初は注文を間違えてばかりで、店長に注意された。でも、店長は怒るのではなく、どうすればよいかを丁寧に教えてくれた。\nそのおかげで、少しずつ仕事ができるようになり、お客さんに「ありがとう」と言われるのが励みになった。今も、あの経験が私の仕事の基礎になっている。','Saat kuliah saya kerja paruh waktu di kafe. Awalnya sering salah pesanan dan ditegur manajer. Tapi manajer tidak marah dan mengajari dengan sabar. Berkat itu saya sedikit demi sedikit bisa bekerja dan ucapan terima kasih pelanggan jadi penyemangat. Sampai kini pengalaman itu jadi dasar pekerjaan saya.',
   ('店長は「私」が間違えたとき、どうしたか。',['怒らずに丁寧に教えてくれた','すぐにやめさせた','何も言わなかった','他の人に代わらせた'],0,'Mengajari dengan sabar.','怒るのではなく、どうすればよいかを丁寧に教えてくれた',P1),
   ('「私」は今、あの経験をどう思っているか。',['仕事の基礎になっている','忘れたい','役に立たなかった','つらいだけだった'],0,'Dasar pekerjaan.','あの経験が私の仕事の基礎になっている',P2)),
 C('日本には、ほかの国にあまり見られない「自動販売機」の文化がある。飲み物だけでなく、食べ物や傘まで買える機械もある。夜でも安全に買い物ができるのが人気の理由の一つだ。\nしかし、電気を多く使うことや、ごみの問題を指摘する人もいる。便利さと環境の負担のバランスを考える必要があるだろう。','Jepang punya budaya mesin penjual otomatis yang jarang di negara lain. Bukan hanya minuman, ada yang menjual makanan sampai payung. Salah satu alasan populer adalah aman berbelanja bahkan malam hari. Namun ada yang menyoroti pemakaian listrik dan sampah. Perlu menimbang keseimbangan antara kepraktisan dan beban lingkungan.',
   ('自動販売機が人気の理由は何か。',['夜でも安全に買い物ができる','必ず安い','店員が親切だ','種類が少ない'],0,'Aman berbelanja malam.','夜でも安全に買い物ができる',P1),
   ('筆者は何が必要だと言っているか。',['便利さと環境の負担のバランスを考えること','機械をなくすこと','もっと増やすこと','値段を下げること'],0,'Menimbang keseimbangan.','便利さと環境の負担のバランスを考える必要',P2)),
 C('私の祖父は、毎朝五時に起きて畑に出る。育てているのは、トマトやきゅうりなどの野菜だ。祖父は「野菜は毎日顔を見てやると、よく育つ」と言う。\n夏休みに畑を手伝ったとき、収穫した野菜をその場で食べた。店で買う野菜よりずっと甘くて、驚いた。以来、私は食べ物がどこでどう作られるかに関心を持つようになった。','Kakek saya bangun jam lima tiap pagi dan pergi ke kebun menanam tomat dan timun. Katanya sayur tumbuh baik jika dilihat tiap hari. Saat membantu di kebun saat liburan musim panas saya memakan sayur panen di tempat. Jauh lebih manis dari yang dibeli di toko dan saya kaget. Sejak itu saya tertarik pada di mana dan bagaimana makanan dibuat.',
   ('祖父は野菜をよく育てるために何をしているか。',['毎日顔を見てやる','毎日水をたくさんやる','肥料を多く使う','夜に畑へ行く'],0,'Melihatnya tiap hari.','毎日顔を見てやると、よく育つ',P1),
   ('「私」は夏休みの経験のあと、どう変わったか。',['食べ物がどう作られるかに関心を持った','畑が嫌いになった','野菜を食べなくなった','農業をやめた'],0,'Tertarik cara makanan dibuat.','どこでどう作られるかに関心を持つようになった',P2)),
 C('日本の電車は時間にとても正確だ。数分の遅れでも、駅員が謝罪のアナウンスをする。外国から来た人はこれに驚くが、日本人にとっては当然のことと考えられている。\nただし、正確さを守るために、運転手や駅員にかかる負担は小さくない。時間を守ることと、働く人の健康との両立が課題だ。','Kereta Jepang sangat tepat waktu. Walau terlambat beberapa menit petugas stasiun mengumumkan permintaan maaf. Orang asing terkejut tapi bagi orang Jepang dianggap wajar. Namun beban bagi masinis dan petugas untuk menjaga ketepatan tidak kecil. Menyeimbangkan ketepatan waktu dan kesehatan pekerja adalah tantangan.',
   ('日本の電車について、正しいものはどれか。',['数分遅れても謝罪のアナウンスがある','よく大幅に遅れる','外国人は気にしない','運転手は楽だ'],0,'Ada permintaan maaf walau terlambat beberapa menit.','数分の遅れでも、駅員が謝罪のアナウンス',P1),
   ('課題は何か。',['時間を守ることと働く人の健康の両立','電車の数を減らすこと','料金を上げること','外国人を減らすこと'],0,'Menyeimbangkan ketepatan dan kesehatan pekerja.','時間を守ることと、働く人の健康との両立',P2)),
 C('友達の結婚式に出席した。会場には、新郎新婦の子どものころの写真が飾られていて、二人の歩みがよく分かった。\n式の最後に、新婦が両親に手紙を読んだとき、会場のみんなが涙を流した。私は、結婚式とは、二人のためだけでなく、周りの人への感謝を伝える場でもあるのだと感じた。','Saya menghadiri pernikahan teman. Di tempat dipajang foto masa kecil kedua mempelai sehingga perjalanan mereka terlihat. Di akhir acara ketika mempelai wanita membacakan surat untuk orangtua semua menangis. Saya merasa pernikahan bukan hanya untuk dua orang tapi juga tempat menyampaikan terima kasih pada orang sekitar.',
   ('会場に飾られていたものは何か。',['二人の子どものころの写真','二人の仕事の道具','旅行の写真','両親の絵'],0,'Foto masa kecil mereka.','子どものころの写真が飾られていて',P1),
   ('「私」は結婚式をどういう場だと感じたか。',['周りの人への感謝を伝える場でもある','二人だけのための場だ','お金を使う場だ','写真を撮る場だ'],0,'Tempat menyampaikan terima kasih.','周りの人への感謝を伝える場でもある',P2)),
 C('私の弟は、ゲームが好きで、毎日何時間もしていた。両親は心配したが、弟は「ゲームで世界中の人と友達になれた」と言う。\n実際、弟は海外の友達と英語でやりとりするうちに、英語が上手になった。今では、ゲームの会社で働くことが夢だそうだ。何事も、使い方次第で大きな力になるのだと思った。','Adik saya suka game dan bermain berjam-jam tiap hari. Orangtua khawatir tapi adik bilang lewat game ia berteman dengan orang di seluruh dunia. Nyatanya, berinteraksi dengan teman luar negeri dalam bahasa Inggris membuat bahasa Inggrisnya mahir. Kini impiannya bekerja di perusahaan game. Saya pikir apa pun bisa jadi kekuatan besar tergantung cara pakai.',
   ('弟はゲームを通してどうなったか。',['英語が上手になった','成績が下がった','目が悪くなった','友達がいなくなった'],0,'Bahasa Inggrisnya mahir.','英語が上手になった',P1),
   ('「私」の考えは何か。',['何事も使い方次第で大きな力になる','ゲームは悪いものだ','弟は遊びすぎだ','英語は大切ではない'],0,'Tergantung cara pakai.','使い方次第で大きな力になる',P2)),
 C('この町には、年に一度、「ほたる祭り」がある。夜、川のそばに静かに集まって、ほたるの光を眺める祭りだ。派手な音楽や出店はなく、静けさを楽しむのが特徴だ。\nほたるは、きれいな水がなければ生きられない。祭りには、川をきれいに保とうという町の人の気持ちが込められている。','Di kota ini setahun sekali ada festival kunang-kunang. Malam hari orang berkumpul tenang di tepi sungai menikmati cahaya kunang-kunang. Tak ada musik meriah atau kios, cirinya menikmati ketenangan. Kunang-kunang tak bisa hidup tanpa air bersih. Festival mengandung perasaan warga untuk menjaga kebersihan sungai.',
   ('ほたる祭りの特徴は何か。',['静けさを楽しむ','派手な音楽がある','出店が多い','昼に行われる'],0,'Menikmati ketenangan.','静けさを楽しむのが特徴',P1),
   ('祭りに込められた気持ちは何か。',['川をきれいに保とうという気持ち','観光客を増やしたい気持ち','お金を集めたい気持ち','夏を楽しみたい気持ち'],0,'Menjaga kebersihan sungai.','川をきれいに保とうという町の人の気持ち',P2)),
 C('スーパーでは、賞味期限が近い食品を安く売ることがある。「まだ食べられるのに捨ててしまうのはもったいない」という考えからだ。\nこの取り組みで、捨てられる食品が減り、お客さんは安く買える。店にとっても、ごみを減らせるという利点がある。私も買い物のときは、必要な分だけ、できるだけ使い切れる量を買うようにしている。','Supermarket kadang menjual murah makanan yang mendekati tanggal kedaluwarsa, berdasarkan pikiran sayang membuang yang masih bisa dimakan. Dengan upaya ini makanan terbuang berkurang dan pelanggan membeli murah. Bagi toko juga ada keuntungan mengurangi sampah. Saya sendiri membeli hanya yang perlu dan dalam jumlah yang bisa dihabiskan.',
   ('賞味期限が近い食品を安く売る理由は何か。',['まだ食べられるのに捨てるのはもったいないから','店が古くなるから','お客が少ないから','値段を上げたいから'],0,'Sayang membuang yang masih bisa dimakan.','まだ食べられるのに捨ててしまうのはもったいない',P1),
   ('この取り組みの利点として正しいものはどれか。',['捨てられる食品が減る','食品が高くなる','店の人が増える','種類が減る'],0,'Makanan terbuang berkurang.','捨てられる食品が減り',P2)),
 C('高校生のとき、私は部活動で毎日遅くまで練習していた。つらいこともあったが、仲間と一緒に頑張るうちに、強い絆が生まれた。\n卒業して十年たった今でも、そのころの仲間とは時々会っている。あのとき苦労を分け合った経験は、私にとって何より大切な宝物だ。','Saat SMA saya berlatih klub hingga larut tiap hari. Ada hal berat tapi seiring berusaha bersama teman muncul ikatan kuat. Sepuluh tahun setelah lulus saya masih sesekali bertemu teman saat itu. Pengalaman berbagi kesulitan saat itu adalah harta terpenting bagi saya.',
   ('「私」は部活動でどんな経験をしたか。',['仲間と頑張って強い絆が生まれた','一人で練習した','すぐにやめた','試合に出られなかった'],0,'Ikatan kuat dengan teman.','強い絆が生まれた',P1),
   ('「私」にとって、あの経験は何か。',['何より大切な宝物','忘れたい思い出','役に立たなかったこと','つらいだけの時間'],0,'Harta terpenting.','何より大切な宝物だ',P2)),
 C('日本語を勉強している外国人の中には、「敬語が難しい」と言う人が多い。尊敬語や謙譲語など、相手によって言い方を使い分けなければならないからだ。\nしかし、日本人でも敬語を間違えることは少なくない。大切なのは、完璧に話すことよりも、相手を思いやる気持ちを示すことだと言えるだろう。','Banyak orang asing yang belajar bahasa Jepang berkata keigo sulit karena harus membedakan cara bicara tergantung lawan, seperti sonkeigo dan kenjougo. Namun orang Jepang pun tak jarang keliru keigo. Yang penting bukan berbicara sempurna tetapi menunjukkan perasaan peduli pada lawan bicara.',
   ('敬語が難しいと言われる理由は何か。',['相手によって言い方を使い分けるから','文字が多いから','発音が難しいから','辞書がないから'],0,'Harus membedakan cara bicara.','相手によって言い方を使い分けなければならない',P1),
   ('筆者が大切だと考えていることは何か。',['相手を思いやる気持ちを示すこと','完璧に話すこと','敬語を使わないこと','早く話すこと'],0,'Menunjukkan kepedulian.','相手を思いやる気持ちを示すこと',P2)),
]
